    expand:'M8 3H3v5M16 3h5v5M21 16v5h-5M8 21H3v-5',
    shrink:'M3 8h5V3M16 3v5h5M21 16h-5v5M8 21v-5H3',
    play:'m8 5 11 7-11 7Z',left:'m14 6-6 6 6 6M8 12h12',right:'m10 6 6 6-6 6M4 12h12',
